function validate([students, sandwiches]) {
  if (students.length < 1 || students.length > 100) return 'There must be 1 to 100 students.';
  if (sandwiches.length !== students.length) return 'There must be exactly one sandwich per student.';
  if (students.some(v => v !== 0 && v !== 1)) return 'Each student wants 0 or 1.';
  if (sandwiches.some(v => v !== 0 && v !== 1)) return 'Each sandwich is 0 or 1.';
  return null;
}

