function countStudents(students, sandwiches) {
  const count = [0, 0];
  for (const wish of students) {
    count[wish]++;
  }

  for (let i = 0; i < sandwiches.length; i++) {
    const top = sandwiches[i];
    if (count[top] === 0) {
      return sandwiches.length - i;
    }
    count[top]--;
  }
  return 0;
}

