function countStudents(students, sandwiches) {
  // Run the line exactly as described, stopping after a full lap of refusals.
  const line = students.slice();
  const stack = sandwiches.slice();
  let refusals = 0;
  while (line.length > 0 && refusals < line.length) {
    const student = line.shift();
    if (student === stack[0]) {
      stack.shift();
      refusals = 0;
    } else {
      line.push(student);
      refusals++;
    }
  }
  return line.length;
}

