function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  const studentOnes = rand();
  const sandwichOnes = rand() < 0.5 ? studentOnes : rand();
  const students = Array.from({ length: n }, () => (rand() < studentOnes ? 1 : 0));
  const sandwiches = Array.from({ length: n }, () => (rand() < sandwichOnes ? 1 : 0));
  return [students, sandwiches];
}
